 "content": "def transform(grid):
    # Color 2 marks the perimeter-gap cells connecting sparse object fragments.
    # Work only inside the occupied bounding box and fill background gaps on
    # rows/columns spanning foreground markers.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for r in range(r0, r1 + 1):
        cs = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
